import torch


def gen_inputs(ctx, device):
    shape = ctx["noise__shape"]
    dtype = getattr(torch, ctx["noise__dtype"])
    if ctx["training"]:
        # Benchmark path: noise = torch.rand_like(inp)
        noise = torch.rand(shape, dtype=dtype, device=device)
    else:
        # Test path: noise uniform in [lower, upper]
        lower = ctx["lower"]
        upper = ctx["upper"]
        noise = torch.rand(shape, dtype=dtype, device=device) * (upper - lower) + lower
    return {"noise": noise}


def run(self, noise, lower, upper, training):
    return torch.ops.aten.rrelu_with_noise_functional(
        self, noise, lower, upper, training, None
    )
